+std::vector<NoteObject> reconcile_monophonic_pitch_boundaries(const Audio& audio,
+                                                              const pitch_editor::F0Track& track,
+                                                              const NoteExtractorConfig& extractor,
+                                                              std::vector<NoteObject> notes) {
+  if (notes.size() < 2) return notes;
+
+  std::vector<NoteObject> reconciled;
+  reconciled.reserve(notes.size());
+  const int64_t sample_count = static_cast<int64_t>(audio.size());
+  const int total_frames = track.n_frames();
+  bool did_merge = false;
+
+  for (size_t start = 0; start < notes.size();) {
+    const double first_hz = notes[start].median_hz;
+    if (!std::isfinite(first_hz) || first_hz <= 0.0) {
+      reconciled.push_back(std::move(notes[start]));
+      ++start;
+      continue;
+    }
+
+    double minimum_hz = first_hz;
+    double maximum_hz = first_hz;
+    size_t end = start + 1;
+    while (end < notes.size() && notes[end - 1].frame_end == notes[end].frame_start) {
+      const double next_hz = notes[end].median_hz;
+      if (!std::isfinite(next_hz) || next_hz <= 0.0) break;
+
+      const double candidate_minimum = std::min(minimum_hz, next_hz);
+      const double candidate_maximum = std::max(maximum_hz, next_hz);
+      const double span_cents =
+          constants::kCentsPerOctave * std::log2(candidate_maximum / candidate_minimum);
+      if (!std::isfinite(span_cents) ||
+          span_cents > extractor.segmenter.segmentation_threshold_cents) {
+        break;
+      }
+      minimum_hz = candidate_minimum;
+      maximum_hz = candidate_maximum;
+      ++end;
+    }
+
+    if (end == start + 1) {
+      reconciled.push_back(std::move(notes[start]));
+    } else {
+      const int frame_start = notes[start].frame_start;
+      const int frame_end = notes[end - 1].frame_end;
+      const pitch_editor::F0Track window = track_window(track, frame_start, frame_end);
+      reconciled.push_back(make_note(audio, 0, sample_count, window, frame_start, total_frames,
+                                     frame_start, frame_end, extractor));
+      did_merge = true;
+    }
+    start = end;
+  }
+
+  if (did_merge) repair_rederived_note_set_bounds(audio, track, reconciled, extractor);
+  return reconciled;
+}
