+sonare::Audio boundary_pitch_motion(int sample_rate, int motion_case) {
+  std::vector<float> samples(static_cast<size_t>(std::lround(2.0 * sample_rate)), 0.0f);
+  double phase = 0.0;
+  for (int sample = static_cast<int>(0.2 * sample_rate);
+       sample < static_cast<int>(1.8 * sample_rate); ++sample) {
+    const double t = static_cast<double>(sample) / sample_rate - 0.2;
+    double cents = 0.0;
+    switch (motion_case) {
+      case 0:
+        cents = t < 0.4 ? 0.0 : (t < 0.45 ? 70.0 : 30.0);
+        break;
+      case 1:
+        cents = 75.0 * std::sin(sonare::constants::kTwoPiD * 6.0 * t);
+        break;
+      case 2:
+        cents = 50.0 * std::sin(sonare::constants::kTwoPiD * 6.0 * t);
+        break;
+      case 3:
+        cents = 300.0 * t / 1.6;
+        break;
+      case 4:
+        cents = t < 0.8 ? 0.0 : 100.0;
+        break;
+      case 5:
+        cents = static_cast<int>(t / 0.2) % 2 == 0 ? 0.0 : 100.0;
+        break;
+      case 6:
+        cents = t < 0.4 ? 0.0 : (t < 0.8 ? 40.0 : (t < 1.2 ? 80.0 : 120.0));
+        break;
+      default:
+        return sonare::Audio::from_buffer(samples.data(), samples.size(), sample_rate);
+    }
+    phase += sonare::constants::kTwoPiD * 220.0 * std::pow(2.0, cents / 1200.0) / sample_rate;
+    const double edge = std::min({1.0, t / 0.004, (1.6 - t) / 0.008});
+    double value = 0.0;
+    for (int harmonic = 1; harmonic <= 5; ++harmonic) {
+      value += std::sin(harmonic * phase) / harmonic;
+    }
+    samples[static_cast<size_t>(sample)] = static_cast<float>(0.18 * edge * value);
+  }
+  return sonare::Audio::from_buffer(samples.data(), samples.size(), sample_rate);
+}
