+sonare::Audio same_pitch_with_silent_gap(int sample_rate) {
+  constexpr double kFirstOnset = 0.2;
+  constexpr double kNoteDuration = 0.6;
+  constexpr double kSecondOnset = 1.2;
+  constexpr double kAttackSeconds = 0.004;
+  constexpr double kReleaseSeconds = 0.008;
+  std::vector<float> samples(static_cast<size_t>(std::lround(2.2 * sample_rate)), 0.0f);
+  double phase = 0.0;
+  for (const double onset : {kFirstOnset, kSecondOnset}) {
+    const int64_t start = static_cast<int64_t>(std::llround(onset * sample_rate));
+    const int64_t count = static_cast<int64_t>(std::llround(kNoteDuration * sample_rate));
+    for (int64_t offset = 0; offset < count; ++offset) {
+      const double t = static_cast<double>(offset) / sample_rate;
+      const double edge =
+          std::min({1.0, t / kAttackSeconds, (kNoteDuration - t) / kReleaseSeconds});
+      phase += sonare::constants::kTwoPiD * 220.0 / sample_rate;
+      double value = 0.0;
+      for (int harmonic = 1; harmonic <= 5; ++harmonic) {
+        value += std::sin(harmonic * phase) / harmonic;
+      }
+      samples[static_cast<size_t>(start + offset)] = static_cast<float>(0.18 * edge * value);
+    }
+  }
+  return sonare::Audio::from_buffer(samples.data(), samples.size(), sample_rate);
+}
