+TEST_CASE("monophonic note boundaries reconcile sub-threshold pitch motion",
+          "[note_transcriber][pitch_boundary]") {
+  constexpr int expected_note_counts[] = {1, 1, 1, 3, 2, 8, 2};
+  for (const int sample_rate : {22050, 44100}) {
+    for (int motion_case = 0; motion_case < 7; ++motion_case) {
+      const std::vector<TranscribedNote> notes =
+          transcribe_notes(boundary_pitch_motion(sample_rate, motion_case));
+      INFO("sample rate " << sample_rate << ", motion case " << motion_case << ", detected notes "
+                          << notes.size());
+      CHECK(notes.size() == static_cast<size_t>(expected_note_counts[motion_case]));
+    }
+
+    const std::vector<TranscribedNote> gapped_notes =
+        transcribe_notes(same_pitch_with_silent_gap(sample_rate));
+    INFO("same-pitch notes separated by a voiced-frame gap at " << sample_rate << " Hz");
+    CHECK(gapped_notes.size() == 2);
+    for (const TranscribedNote& note : gapped_notes) CHECK(note.note == 57);
+  }
+}
